import { AboutMeComponent } from '../components/AboutMeComponent';
import { SkillsComponentR } from '../components/skillPrincipal/SkillsComponentR';
import { ContactPage } from '../pages/contact-page/contact-page';
import { HomePage } from '../pages/home-page/home-page';
import { NotFoundPage } from '../pages/not-found-page/not-found-page';
import { ProjectDetailPage } from '../pages/project-datail-page/project-datail-page';
import { ProjectGalleryPage } from '../pages/project-gallery-page/project-gallery-page';
import { RouterName } from './router-name';

export const routers = [
  {
    path: RouterName.root,
    component: HomePage,
  },
  {
    path: RouterName.about,
    component: AboutMeComponent,
  },
  {
    path: RouterName.skills,
    component: SkillsComponentR,
    children: [
      {
        path: RouterName.notFound,
        component: ProjectDetailPage,
      },
    ],
  },

  {
    path: RouterName.projectGallery,
    component: ProjectGalleryPage,
  },
  {
    path: RouterName.contact,
    component: ContactPage,
  },
  { path: RouterName.notFound, component: NotFoundPage },
];
