import { useColorMode } from '@chakra-ui/color-mode';
import { Image } from '@chakra-ui/image';
import { Stack, Flex, Box, Text } from '@chakra-ui/layout';
import { useBreakpointValue } from '@chakra-ui/media-query';
import React from 'react';

import fondo from '../../assets/img/banner-bg.png';

import jonnathan1 from '../../assets/img/jonnathan1.jpg';

import { AddressComponents } from '../../components/maps/AddressComponents';


export const HomePage = () => {
    const { colorMode } = useColorMode();
    const isDark = colorMode === 'dark';
    const imageBoxSize = useBreakpointValue({
        base: '200px',
        md: '300px',
        lg: '400px',
    });
    const fontSizeTitle = useBreakpointValue({
        base: '2xl',
        md: '4xl',
        lg: '6xl',
    });
    const fontSizeSubtitle = useBreakpointValue({
        base: 'xl',
        md: '2xl',
        lg: '3xl',
    });
    // const buttonSize = useBreakpointValue({ base: 'md', md: 'lg', lg: 'xl' });

    const styles = {
        backgroundImage: `url(${fondo})`,
        backgroundSize: 'cover',
        backgroundRepeat: 'no-repeat',
        backgroundPosition: 'center',
    };

    return (
        <>
            {/* <div  style={styles}> */}

            <Box marginTop="40px" marginBottom="50px">
                <Stack direction="column" spacing={8} p={3} alignItems="center">
                    <div data-aos="zoom-in-down">
                        <Image
                            src={jonnathan1}
                            alt="Banner Image"
                            borderRadius="full"
                            boxSize={imageBoxSize}
                            objectFit="cover"
                        />
                    </div>

                    <Flex
                        direction="column"
                        justify="center"
                        alignItems="center"
                        textAlign="center"
                    >
                        <div>
                            <Text
                                fontSize={fontSizeSubtitle}
                                fontWeight="bold"
                                color={isDark ? 'white' : 'black'}
                            >
                                JONNATHAN GALLEGOS
                            </Text>
                        </div>
                        {/* <div data-aos="zoom-in-down"> */}
                        <Text
                            fontSize={fontSizeTitle}
                            fontWeight="bold"
                            color={isDark ? 'white' : 'black'}
                        >
                            ¡BIENVENIDO A MI PORTAFOLIO!
                        </Text>
                        {/* </div> */}

                        {/* <div data-aos="zoom-in-down"> */}
                        <Text
                            fontSize={fontSizeSubtitle}
                            color={isDark ? 'white' : 'black'}
                        >
                            DESARROLLADOR DE SOFTWARE EN CUENCA
                        </Text>
                        {/* </div> */}
                    </Flex>
                </Stack>
            </Box>
            <AddressComponents />
        </>
    );
};
