import {
    Accordion,
    AccordionButton,
    AccordionIcon,
    AccordionItem,
    AccordionPanel,
    Button,
    Image,
    useColorMode
} from '@chakra-ui/react';
import React, { useEffect, useState } from 'react'

import { Box, Flex, Heading, IconButton, useBreakpointValue } from "@chakra-ui/react";
import { FiMenu } from "react-icons/fi";

import { Menu, MenuButton, MenuItem, MenuList } from "@chakra-ui/react";
import { FaSun, FaMoon, FaInstagram, FaGithub, FaLinkedin, FaStar, FaMailBulk, FaFolder, FaWindowMinimize } from 'react-icons/fa';
import { AiFillHome } from 'react-icons/ai';
import { IoMdPerson } from 'react-icons/io';

import { scrollToSection1 } from '../scrollToSection'


import certificates from './../../assets/curriculum/Certificados.pdf';
import { MenuItems } from './MenuItems';
import { ChevronDownIcon } from '@chakra-ui/icons';

import me from '../../assets/img/jonnathan.jpg';
import { URLS } from '../../util/url';
import { RouterName } from '../../router/router-name';
import { useCustomNavigate } from '../../hooks/custom-navigate';

export const HeaderComponent = () => {
    const { colorMode, toggleColorMode } = useColorMode();
    const isDark = colorMode === 'dark';
    const displayIcons = useBreakpointValue({ base: false, lg: true });
    const [windowSize, setWindowSize] = useState({ width: 0, height: 0 });

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        handleResize();
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const scrollToSection = (e) => scrollToSection1(e);

    const { handlerNavigate, handlerWindowBlank } = useCustomNavigate();

    const navigate = (path) => handlerNavigate(path);

    const redirectLink = (e) => handlerWindowBlank(URLS[e.toString()]);

    const navItems = [
        { icon: <AiFillHome />, label: 'Home', section: 'home' },
        { icon: <IoMdPerson />, label: 'About me', section: 'about' },
        { icon: <FaStar />, label: 'Skills', section: 'skills' },
        { icon: <FaFolder />, label: 'Projects', section: 'proyects' },
        { icon: <FaMailBulk />, label: 'Contact', section: 'contact' },
    ];

    const navItems1 = [
        { label: 'HOME', leftIcon: <AiFillHome />, go: RouterName.root, margin: 0 },
        { label: 'ABOUT ME', leftIcon: <IoMdPerson />, go: RouterName.about, margin: 1 },
        { label: 'SKILLS', leftIcon: <FaStar />, go: RouterName.skills, margin: 1 },
        { label: 'PROJECTS', leftIcon: <FaFolder />, go: RouterName.projectGallery, margin: 1 },
        { label: 'CONTACT', leftIcon: <FaMailBulk />, go: RouterName.contact, margin: 1 },
    ];

    return (
        <>
            <Box bg={isDark ? 'blackAlpha.900' : 'whiteAlpha.900'} py={3} >
                <Flex align="center" justify="space-between" maxW="1200px" mx="auto" px={3}>
                    <Heading as="h1" size="lg">
                        <a href='/'>  JBGT</a>
                    </Heading>

                    {displayIcons ? (<>
                        <Flex align="center">
                            {navItems1.map((item, index) => (
                                <Button
                                    key={index}
                                    border='none'
                                    background='transparent'
                                    leftIcon={item.leftIcon}
                                    variant='solid'
                                    marginLeft={item.margin}
                                    onClick={() => navigate(item.go)}>
                                    {item.label}
                                </Button>
                            ))}

                            <Menu>
                                <MenuButton as={Button} rightIcon={<ChevronDownIcon />} aria-label="Menú" variant="ghost" marginLeft={1}>
                                    LINKS
                                </MenuButton>
                                <MenuList>

                                    <MenuItems redirect={redirectLink} />
                                </MenuList>

                            </Menu>

                        </Flex></>
                    ) : (
                        <div></div>
                    )}

                    {displayIcons ? (
                        <Flex align="center">

                            <IconButton icon={<FaLinkedin />} isRound='true' onClick={() => redirectLink(1)}></IconButton>
                            <IconButton ml={2} icon={<FaInstagram />} isRound='true' onClick={() => redirectLink(2)}></IconButton>
                            <IconButton ml={2} icon={<FaGithub />} isRound='true' onClick={() => redirectLink(3)}></IconButton>
                            <IconButton ml={8} icon={isDark ? <FaSun /> : <FaMoon />} isRound='true' onClick={toggleColorMode}></IconButton>

                        </Flex>
                    ) : (
                        <Menu>
                            <MenuButton as={IconButton} icon={<FiMenu />} aria-label="Menú" variant="ghost" fontSize="xl" />
                            <MenuList>

                                <Box css={windowSize.height < 400 ? {
                                    overflowY: "scroll",
                                    maxHeight: "190px",
                                    "&::-webkit-scrollbar": {
                                        width: "4px",
                                    },
                                    "&::-webkit-scrollbar-track": {
                                        background: "#f1f1f1",
                                    },
                                    "&::-webkit-scrollbar-thumb": {
                                        background: "#888",
                                    },
                                    "&::-webkit-scrollbar-thumb:hover": {
                                        background: "#555",
                                    },
                                } : {}}>

                                    {navItems1.map((item) => (
                                        <MenuItem key={item.label} icon={item.icon} onClick={() => navigate(item.go)}>
                                            <strong>{item.label}</strong>
                                        </MenuItem>
                                    ))}

                                    <MenuItem icon={isDark ? <FaSun /> : <FaMoon />} isRound='true' onClick={toggleColorMode}></MenuItem>

                                    <Accordion allowToggle >
                                        <AccordionItem style={{ marginTop: '4px' }}>
                                            <h2>
                                                <AccordionButton>
                                                    <Box as="span" flex='1' textAlign='left' >
                                                        <strong>LINKS</strong>

                                                    </Box>
                                                    <AccordionIcon />
                                                </AccordionButton>
                                            </h2>
                                            <AccordionPanel pb={4}>
                                                <Box css={{
                                                    overflowY: "scroll",
                                                    maxHeight: "150px",
                                                    "&::-webkit-scrollbar": {
                                                        width: "4px",
                                                    },
                                                    "&::-webkit-scrollbar-track": {
                                                        background: "#f1f1f1",
                                                    },
                                                    "&::-webkit-scrollbar-thumb": {
                                                        background: "#888",
                                                    },
                                                    "&::-webkit-scrollbar-thumb:hover": {
                                                        background: "#555",
                                                    },
                                                }}>
                                                    <MenuItems redirect={redirectLink} />
                                                </Box>

                                            </AccordionPanel>
                                        </AccordionItem>

                                        <AccordionItem>
                                            <h2>
                                                <AccordionButton>
                                                    <Box as="span" flex='1' textAlign='left'>
                                                        <strong>Personal</strong>

                                                    </Box>
                                                    <AccordionIcon />
                                                </AccordionButton>
                                            </h2>
                                            <AccordionPanel pb={4}>

                                                <a href="https://drive.google.com/file/d/18TNc_o6VmjtgK6KcdWFTW_O0N49_Y-d2/view?usp=sharing" target='_blank'>
                                                    <MenuItem minH='40px'  >
                                                        <Image
                                                            boxSize='2rem'
                                                            borderRadius='full'
                                                            src={me}

                                                            alt='Simon the pensive'
                                                            mr='12px'
                                                        />
                                                        <span>
                                                            <strong>CV - Curriculum</strong>
                                                        </span>
                                                    </MenuItem>
                                                </a>

                                                <a href={certificates} target='_blank'>
                                                    <MenuItem minH='40px' >
                                                        <Image
                                                            boxSize='2rem'
                                                            borderRadius='full'
                                                            src='https://doctor-cv.com/wp-content/uploads/2020/08/gold-trophy-with-name-plate-winner-competition_68708-545-1.jpg'
                                                            alt='Simon the pensive'
                                                            mr='12px'
                                                        />
                                                        <span>
                                                            <strong>Certificados</strong>
                                                        </span>
                                                    </MenuItem>
                                                </a>

                                            </AccordionPanel>
                                        </AccordionItem>
                                    </Accordion>
                                </Box>
                            </MenuList>
                        </Menu>
                    )}
                </Flex>
            </Box>
        </>
    );
}
