import React, { useState, useRef } from 'react';
import { Form, Field } from 'react-final-form';
import { classNames } from 'primereact/utils';
import emailjs from 'emailjs-com';
import { Input, Text, InputGroup, InputRightElement, Textarea, Box, useColorMode, useToast, useMediaQuery, Icon, Stack, Flex, useColorModeValue } from '@chakra-ui/react';
import { FaUserCheck, FaMailBulk } from 'react-icons/fa'
import { SiProbot } from 'react-icons/si'
import { AddressComponents } from '../../components/maps/AddressComponents';
import { HeadingComponent } from '../../components/heading-components/heading-component';
import { ButtonComponent } from '../../components/button-components/button-component';
import { FeatureComponent } from '../../components/feature-component/feature-component';


export const ContactPage = () => {

    const formRef = useRef();

    const [sendMessage, setSendMessage] = useState(false);

    const { colorMode, toggleColorMode } = useColorMode();

    const toast = useToast()

    const toastIdRef = React.useRef()

    const [isLessWith] = useMediaQuery('(max-width: 1000px)');

    const validate = (data) => {
        let errors = {};

        if (!data.user_name) {
            errors.user_name = 'Name is required.';
        }

        if (!data.user_email) {
            errors.user_email = 'Email is required.';
        }
        else if (!/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(data.user_email)) {
            errors.user_email = 'Invalid email address. E.g. example@email.com';
        }

        if (!data.user_topic) {
            errors.user_topic = 'Topic is required.';
        }

        if (!data.message) {
            errors.message = 'Message is required.';
        }

        return errors;
    };

    const onSubmit = (data, form) => {
        setSendMessage(true)

        emailjs.sendForm('service_i7z23kt', 'template_f5m6i8o', formRef.current, 'KRvDmRL5vVWGlhihC')
            .then((result) => {
                console.log(result.text);

                toastIdRef.current = toast({
                    description: '¡Envío de correo exitoso!',
                    status: 'success',
                    duration: 3000,
                    isClosable: true,

                });
                setSendMessage(false);
            }, (error) => {
                console.log(error.text);
                toastIdRef.current = toast({
                    description: '¡Inconveniente al enviar el correo!',
                    status: 'error',
                    duration: 2000,
                    isClosable: true,

                });
                setSendMessage(false);
            });

        form.restart();

    };

    const isFormFieldValid = (meta) => !!(meta.touched && meta.error);

    const getFormErrorMessage = (meta) => {
        return isFormFieldValid(meta) && <small className="p-error">{meta.error}</small>;
    };

    return (
        <>
            <HeadingComponent title={'CONTACT ME!'} />
            <div data-aos="zoom-in-down">
                <Box margin={isLessWith ? 3 : null} marginBottom={10}>
                    <div className="flex align-items-center justify-content-center" >
                        <div className="card p-4 shadow-4 border-round w-full lg:w-6 mb-3" >
                            <div>
                                <Form onSubmit={onSubmit} initialValues={{ user_name: '', user_email: '', user_topic: '', message: '' }} validate={validate} render={({ handleSubmit }) => (
                                    <form ref={formRef} onSubmit={handleSubmit} className="p-fluid">

                                        <div className="mt-3">
                                            <Field name="user_name" render={({ input, meta }) => (
                                                <div className="p-field" data-aos="zoom-in-down">

                                                    <InputGroup>
                                                        <InputRightElement pointerEvents='none'>
                                                            <FaUserCheck color='gray.300' />
                                                        </InputRightElement>
                                                        <Input placeholder='Full name' size='md' variant='filled' id="user_name" {...input} className={classNames({ 'p-invalid': isFormFieldValid(meta) })} />
                                                    </InputGroup>

                                                    {meta.error && meta.touched && (
                                                        <Text as="samp">{getFormErrorMessage(meta)}</Text>
                                                    )}

                                                </div>
                                            )} />
                                        </div>

                                        <div className="mt-2">
                                            <Field name="user_email" render={({ input, meta }) => (
                                                <div className="p-field" >
                                                    <div data-aos="zoom-in-down">
                                                        <InputGroup>
                                                            <InputRightElement pointerEvents='none'>
                                                                <FaMailBulk color='gray.300' />
                                                            </InputRightElement>
                                                            <Input placeholder='Email' variant='filled' id="user_email" {...input} className={classNames({ 'p-invalid': isFormFieldValid(meta) })} />
                                                        </InputGroup>
                                                        {meta.error && meta.touched && (
                                                            <Text as='samp'>{getFormErrorMessage(meta)}</Text>
                                                        )}
                                                    </div>
                                                    {/* {getFormErrorMessage(meta)} */}
                                                </div>
                                            )} />
                                        </div>

                                        <div className="mt-2">
                                            <Field name="user_topic" render={({ input, meta }) => (
                                                <div className="p-field">
                                                    <div data-aos="zoom-in-down">
                                                        <InputGroup>
                                                            <InputRightElement pointerEvents='none'>
                                                                <SiProbot color='gray.300' />
                                                            </InputRightElement>
                                                            <Input placeholder='Topic' variant='filled' id="user_topic" {...input} className={classNames({ 'p-invalid': isFormFieldValid(meta) })} />
                                                        </InputGroup>
                                                        {meta.error && meta.touched && (
                                                            <Text as='samp'> {getFormErrorMessage(meta)}</Text>
                                                        )}
                                                    </div>
                                                </div>
                                            )} />
                                        </div>

                                        <div className="mt-2">
                                            <Field name='message' render={({ input, meta }) => (
                                                <div className='p-field'>
                                                    <div data-aos="zoom-in-down">
                                                        <Textarea placeholder='Message with a summary' variant='filled' id='message' {...input} className={classNames({ 'p-invalid': isFormFieldValid(meta) })} rows={5} cols={30} />
                                                        {meta.error && meta.touched && (
                                                            <Text as='samp'> {getFormErrorMessage(meta)}</Text>
                                                        )}
                                                    </div>
                                                </div>
                                            )} />
                                        </div>


                                        <div className="mt-3 text-center">
                                            <div data-aos="zoom-in-down">
                                                {ButtonComponent('submit', sendMessage, 'Contact')}
                                            </div>
                                        </div>

                                    </form>
                                )} />
                            </div>
                        </div>
                    </div>
                </Box>
            </div>
            <AddressComponents />
        </>
    )
}


export const Feature = ({ text, icon, iconBg }) => {
    return (
        <Stack direction={'row'} align={'center'}>
            <Flex w={8} h={8} align={'center'} justify={'center'} rounded={'full'} bg={iconBg}>
                {icon}
            </Flex>
            <Text fontWeight={600}>{text}</Text>
        </Stack>
    )
}