
import React, { useState, useEffect, useRef } from 'react';
import { Button } from 'primereact/button';
import { Galleria } from 'primereact/galleria';
import { classNames } from 'primereact/utils';
import { PhotosService } from './../../services/PhotosService';

import './../../prime_react/PrimeReactConfig';

import './project-gallery-page.css'
import { Box, Heading, Link, useColorMode, useMediaQuery } from '@chakra-ui/react';

export const ProjectGalleryPage = () => {

    const { colorMode } = useColorMode();
    const isDark = colorMode === 'dark';

    const [isLessWith] = useMediaQuery('(max-width: 1000px)');

    const [images, setImages] = useState(null);
    const [activeIndex, setActiveIndex] = useState(0);
    const [showThumbnails, setShowThumbnails] = useState(false);
    const [isAutoPlayActive, setAutoPlayActive] = useState(true);
    const [isFullScreen, setFullScreen] = useState(false);

    const galleria = useRef(null)

    const responsiveOptions = [
        {
            breakpoint: '1024px',
            numVisible: 5
        },
        {
            breakpoint: '960px',
            numVisible: 4
        },
        {
            breakpoint: '768px',
            numVisible: 3
        },
        {
            breakpoint: '560px',
            numVisible: 1
        }
    ];

    useEffect(() => {
        PhotosService.getImages().then(data => {
            setImages(data)
            // console.log(data)
        }
        );
        bindDocumentListeners();

        return () => unbindDocumentListeners();
    }, []);

    useEffect(() => {
        setAutoPlayActive(galleria.current.isAutoPlayActive())
    }, [isAutoPlayActive]);

    const onItemChange = (event) => {
        setActiveIndex(event.index)
    }

    const toggleFullScreen = () => {
        if (isFullScreen) {
            closeFullScreen();
        }
        else {
            openFullScreen();
        }
    }

    const onFullScreenChange = () => {
        setFullScreen(prevState => !prevState)
    }

    const openFullScreen = () => {
        let elem = document.querySelector('.custom-galleria');
        if (elem.requestFullscreen) {
            elem.requestFullscreen();
        }
        else if (elem.mozRequestFullScreen) {
            elem.mozRequestFullScreen();
        }
        else if (elem.webkitRequestFullscreen) {
            elem.webkitRequestFullscreen();
        }
        else if (elem.msRequestFullscreen) {
            elem.msRequestFullscreen();
        }
    }

    const closeFullScreen = () => {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
        else if (document.mozCancelFullScreen) {
            document.mozCancelFullScreen();
        }
        else if (document.webkitExitFullscreen) {
            document.webkitExitFullscreen();
        }
        else if (document.msExitFullscreen) {
            document.msExitFullscreen();
        }
    }

    const bindDocumentListeners = () => {
        document.addEventListener("fullscreenchange", onFullScreenChange);
        document.addEventListener("mozfullscreenchange", onFullScreenChange);
        document.addEventListener("webkitfullscreenchange", onFullScreenChange);
        document.addEventListener("msfullscreenchange", onFullScreenChange);
    }

    const unbindDocumentListeners = () => {
        document.removeEventListener("fullscreenchange", onFullScreenChange);
        document.removeEventListener("mozfullscreenchange", onFullScreenChange);
        document.removeEventListener("webkitfullscreenchange", onFullScreenChange);
        document.removeEventListener("msfullscreenchange", onFullScreenChange);
    }

    const thumbnailTemplate = (item) => {
        return (
            <div className="grid grid-nogutter justify-content-center">
                <img src={item.thumbnailImageSrc} alt={item.alt} style={{ display: 'block', width: '80px', height: '60px' }} />
            </div>
        );
    }

    const itemTemplate = (item) => {
        if (isFullScreen) {
            return <img src={item.itemImageSrc} alt={item.alt} />
        }

        return <img src={item.itemImageSrc} alt={item.alt} style={{ width: '100%', display: 'block', height: isLessWith ? '' : '550px' }} />
    }

    const renderFooter = () => {
        let autoPlayClassName = classNames('pi', {
            'pi-play': !isAutoPlayActive,
            'pi-pause': isAutoPlayActive
        });

        let fullScreenClassName = classNames('pi', {
            'pi-window-maximize': !isFullScreen,
            'pi-window-minimize': isFullScreen
        });

        return (
            <div className="custom-galleria-footer">
                <Button icon="pi pi-list" onClick={() => setShowThumbnails(prevState => !prevState)} />
                <Button icon={autoPlayClassName} onClick={() => {
                    if (!isAutoPlayActive) {
                        galleria.current.startSlideShow();
                        setAutoPlayActive(true)
                    }
                    else {
                        galleria.current.stopSlideShow();
                        setAutoPlayActive(false)
                    }
                }} />
                {
                    images && (
                        <span className="title-container">
                            <span>{activeIndex + 1}/{images.length}</span>
                            <span className="title">
                                {images[activeIndex].url ? (<a href={images[activeIndex].url} target='_blank'>{images[activeIndex].title}</a>) : (<a >{images[activeIndex].title}</a>)}

                            </span>

                            <span>
                                <Link color='teal.100' href={images[activeIndex].url ? images[activeIndex].url : null} target='_blank'>{images[activeIndex].alt}</Link>
                            </span>
                        </span>
                    )
                }
                <Button icon={fullScreenClassName} onClick={() => toggleFullScreen()} className="fullscreen-button" />
            </div>
        );
    }

    const footer = renderFooter();
    const galleriaClassName = classNames('custom-galleria', {
        'fullscreen': isFullScreen
    });

    return (
        <>
            <Box py={10} textAlign="center" bg={isDark ? 'blackAlpha.500' : 'gray.100'} >
                <Heading as="h3" size="lg" marginBottom={10}>
                    <div data-aos="zoom-in-down">
                        MY PROJECTS
                    </div>

                </Heading>
                <div data-aos="zoom-in-down">

                    <Box marginLeft={1} marginRight={1} marginBottom={6}>
                        <div className="card galleria-demo" style={{ margin: '0 auto', maxWidth: '1000px', }} >
                            <Galleria
                                ref={galleria}
                                value={images}
                                activeIndex={activeIndex}
                                onItemChange={onItemChange}
                                showThumbnails={showThumbnails}
                                showItemNavigators
                                showItemNavigatorsOnHover
                                numVisible={5}
                                circular
                                autoPlay
                                transitionInterval={3000}
                                responsiveOptions={responsiveOptions}
                                item={itemTemplate}
                                thumbnail={thumbnailTemplate}
                                footer={footer}
                                className={galleriaClassName}
                            />
                        </div>
                    </Box>
                </div>
                {/* <Grid templateColumns={{ base: '1fr', md: '1fr 1fr' }} gap={4}>

                    {images.map((img, i) => (

                        console.log()

                        <Box>
                            <div className="card galleria-demo" style={{ margin: '0 auto', maxWidth: '700px' }}>
                                <Galleria
                                    ref={galleria}
                                    value={img.images}
                                    activeIndex={activeIndex}
                                    onItemChange={onItemChange}
                                    showThumbnails={showThumbnails}
                                    showItemNavigators
                                    showItemNavigatorsOnHover
                                    numVisible={5}
                                    circular
                                    autoPlay
                                    transitionInterval={3000}
                                    responsiveOptions={responsiveOptions}
                                    item={itemTemplate}
                                    thumbnail={thumbnailTemplate}
                                    footer={footer}
                                    className={galleriaClassName}
                                />
                            </div>
                        </Box>
                    ))} */}

                {/* <Box>
                   
                </Box> */}

                {/* </Grid> */}
            </Box>
        </>


    );
};
