import { Box, Heading, useColorMode } from '@chakra-ui/react';
import React, { useEffect, useState, useRef } from 'react';

export const AddressComponents = () => {

    const { colorMode } = useColorMode();
    const isDark = colorMode === 'dark';

    const mapRef = useRef(null);

    useEffect(() => {
        const loadMap = () => {
            const mapOptions = {
                center: { lat: -3.009598, lng: -79.007687 }, // Coordenadas iniciales del mapa en el ambiente geografico
                zoom: 10,
                //Vamo a usar el satelite por defecto..
                // mapTypeId: 'satellite',
                mapTypeControl: true,  // para que aparesca el tipo de mapa con el que quiere que se visualice..
                // mapTypeId: 'satellite',

            };

            // Crear el mapa para la visualizaicion ..
            const map = new window.google.maps.Map(mapRef.current, mapOptions);

            // Crear un marcado de la ubicacion..
            new window.google.maps.Marker({
                position: { lat: -3.011807, lng: -79.007435 }, // Coordenadas del marcador de la ubicacion..
                map: map,
                title: 'Mi dirección ',
            });

            // map.setOptions({ mapTypeId: 'satellite' }); // Habilitar el modo de mapa satélite
        };

        if (window.google && window.google.maps) {
            // La API de Google Maps ya se ha cargado
            loadMap();
        } else {
            // Esperar a que se cargue la API de Google Maps
            window.onload = () => {
                loadMap();
            };
        }
    }, []);


    return (
        <>
            <div data-aos="zoom-in-down">
                <Box textAlign="center" bg={isDark ? 'blackAlpha.500' : 'gray.100'} >
                    {/* <Heading as="h3" size="lg" py={10}>
                    DIRECCIÓN

                </Heading> */}

                    <div ref={mapRef} style={{ width: '100%', height: '650px' }}></div>
                </Box>
            </div>
        </>
    );

}

