import React from "react";
import { Box, Button, Flex, Icon, IconButton, Text, Tooltip } from "@chakra-ui/react";
import { FaHome } from "react-icons/fa";
import { useCustomNavigate } from "../../hooks/custom-navigate";

export const SkillCard = ({ skills, size }) => {

    const { handlerNavigate } = useCustomNavigate();

    return (
        <>
            <Box rounded="md" shadow="lg" p={4} maxWidth={size ? '100%' : '900px'} width="100%">
                {skills.map((skill, index) => (
                    <div data-aos="zoom-in-down">
                        <Flex key={index} direction="column" align="center" my={4}>

                            <Flex align="center" justify="space-between" width="100%" mb={4}>
                                <Flex align="center">
                                    <Icon as={skill.icon} boxSize={8} color="blue.500" mr={2} />
                                    {skill.reactIcon && <Icon as={skill.reactIcon} boxSize={8} color="blue.500" />}
                                    <Text fontSize="x0" fontWeight="bold" ml={2}>
                                        {skill.title}
                                    </Text>
                                </Flex>
                                <Text fontSize="md" fontWeight="bold">
                                    {skill.percentage}%
                                    <IconButton aria-label="Search database" background='none' m={1} onClick={() => handlerNavigate(skill.path)}>
                                        <FaHome />
                                    </IconButton>
                                </Text>

                            </Flex>
                            <Flex bg="gray.200" height="8px" borderRadius="4px" overflow="hidden" width="100%" mb={2}>
                                <Box width={`${skill.percentage}%`} height="100%" bg="blue.500" borderRadius="4px" />
                            </Flex>

                        </Flex>
                    </div>
                ))}
            </Box>
        </>
    );
};
