import { Image } from '@chakra-ui/react';

import React, { useEffect, useState } from 'react'

import { MenuItem } from "@chakra-ui/react";

import cc from './../../assets/images/capacitacionesc/ccontinuasinit1.JPG';

import nextGame from './../../assets/images/nexxt/game1p.jpg';

import me from '../../assets/img/jonnathan.jpg';

import { CERTIFICATES } from '../../util/url';

export const MenuItems = ({ redirect }) => {

    const [windowWidth, setWindowWidth] = useState(window.innerWidth);

    useEffect(() => {
        const handleResize = () => {
            setWindowWidth(window.innerWidth)
        }

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
        }

    }, []);

    const items = [
        {
            url: 'https://placekitten.com/120/120',
            name: 'AnimalsCouple',
            auxName: 'AnimalsCouple',
            id: 4,
        },
        {
            url: cc,
            name: 'CContinuas',
            auxName: 'Capacitaciones Continuas',
            id: 5,
        },
        {
            url: 'https://borealtech.com/wp-content/uploads/2018/10/codigo-qr-1024x1024-1.jpg',
            name: 'React QR',
            auxName: 'Auth Google - React QR',
            id: 10,
        },
        {
            url: nextGame,
            name: 'Juego Next',
            auxName: 'Juego Next',
            id: 6,
        },
        {
            url: 'data:image/jpeg;base64,',
            name: 'API POKE',
            auxName: 'API POKE',
            id: 8,
        },
        {
            url: 'https://www.eltiempo.com/files/image_640_428/uploads/2017/10/03/59d322ad01c2c.jpeg',
            name: 'API RICK',
            auxName: 'API RICK',
            id: 9,
        },
        {
            url: 'https://kozub.com.ar/wp-content/uploads/2021/01/What-is-an-API.png',
            name: 'ENDPOINT',
            auxName: 'ENDPOINT',
            id: 11,
        },
        {
            url: 'https://i0.wp.com/www.primefaces.org/wp-content/uploads/2016/10/primeng.png?resize=250%2C250&ssl=1',
            name: 'Auth Google',
            auxName: 'Auth Google - API ChatGPT',
            id: 7,
        }
    ];

    return (
        <>
            {items.map((item, index) => (
                <MenuItem key={index} minH='48px' onClick={() => redirect(item.id)}>
                    <Image
                        boxSize='2rem'
                        borderRadius='full'
                        src={item.url}
                        alt='Fluffybuns the destroyer'
                        mr='12px'
                    />
                    <span>
                        <strong>{windowWidth < 600 ? item.name : item.auxName}</strong>
                    </span>
                </MenuItem>
            ))}

            {
                windowWidth < 400 ?
                    <></> :
                    (
                        <>
                            <a href='https://drive.google.com/file/d/18TNc_o6VmjtgK6KcdWFTW_O0N49_Y-d2/view?usp=sharing' target='_blank'>
                                <MenuItem minH='40px' >
                                    <Image
                                        boxSize='2rem'
                                        borderRadius='full'
                                        src={me}
                                        alt='.'
                                        mr='12px'
                                    />
                                    <span>
                                        <strong>CV - Curriculum</strong>
                                    </span>
                                </MenuItem>
                            </a>

                            <a href={CERTIFICATES} target='_blank'>
                                <MenuItem minH='40px' >
                                    <Image
                                        boxSize='2rem'
                                        borderRadius='full'
                                        src='https://doctor-cv.com/wp-content/uploads/2020/08/gold-trophy-with-name-plate-winner-competition_68708-545-1.jpg'
                                        alt='.'
                                        mr='12px'
                                    />
                                    <span>
                                        <strong>Certificados</strong>
                                    </span>
                                </MenuItem>
                            </a>

                        </>
                    )
            }

        </>
    )
}
