// const p

export const SkillsComponent = () => {

  //Para verificar el tamaño de la pantall..
  const [isLessWith] = useMediaQuery('(max-width: 600px)');

  //Para dar el tamaño a losiconos que estan en ela card..
  const cardSize = useBreakpointValue({ base: isLessWith ? '20%' : '50%', sm: '25%', md: '15%' });

  // const cardSize = useBreakpointValue({ base: '50%', sm: '25%', md: '15%' });
  // const cardSize = useBreakpointValue({ base: '90%', sm: '45%', md: '30%' });

  const OverlayTwo = () => (
    <ModalOverlay
      bg='none'
      backdropFilter='auto'
      backdropInvert='80%'
      backdropBlur='2px'
    />
  )

  const { isOpen, onOpen, onClose } = useDisclosure()
  const [overlay, setOverlay] = React.useState(<OverlayTwo />)


  return (
    <>
      <Link
        ml="4"
        display="inline-flex"
        alignItems="center"
        color="blue.500"
        fontSize="md"
        fontWeight="bold"
        onClick={() => {
          setOverlay(<OverlayTwo />);
          onOpen();
        }}
      >
        See more
        <Icon as={GoLinkExternal} boxSize={4} ml={2} />
      </Link>

      {/* <Button
        ml='4'
        onClick={() => {
          setOverlay(<OverlayTwo />)
          onOpen()
        }}
      >
        Use Overlay two
      </Button> */}

      <Modal isCentered isOpen={isOpen} onClose={onClose} size='xl'>
        {overlay}
        <ModalContent>
          <ModalHeader>TIC's</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {/* <Text>Custom backdrop filters!</Text> */}

            {/* Commet init */}

            <Box textAlign="left">
              <Heading as="h2" size="x1" mb={6}>
                Tecnología aprendida en mi formación.
              </Heading>
              {/* justify="center"  */}
              <Flex wrap="wrap" justify="center" >
                {skillsData.map((skill, index) => (
                  // <CardSkill  key={index} title={skill.title} icon={skill.icon} percentage={skill.percentage} size={cardSize} />
                  <CardSkill key={index} icon={skill.icon} size={cardSize} />

                ))}
              </Flex>
            </Box>

            {/* Final commetn */}
          </ModalBody>
          <ModalFooter>
            <Button onClick={onClose}>Close</Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </>

  );
};

