import { Box, Flex, Heading, Icon, Image, Text, useColorMode, useColorModeValue, useMediaQuery } from '@chakra-ui/react';
import React from 'react';
import jonathanImage from '../assets/img/jonnathan.jpg';
import jonnathan1 from '../assets/img/jonnathan1.jpg';

//Another import 
import { useState, useEffect } from "react";

import TrackVisibility from 'react-on-screen';
import { FeatureComponent } from './feature-component/feature-component';
import { FaMailBulk } from 'react-icons/fa';

export const AboutMeComponent = () => {

    //Para verificar el tamaño de la pantall..
    const [isLessWith] = useMediaQuery('(max-width: 500px)');

    const { colorMode, toggleColorMode } = useColorMode();
    const isDark = colorMode === 'dark';


    const [loopNum, setLoopNum] = useState(0);
    const [isDeleting, setIsDeleting] = useState(false);
    const [text, setText] = useState('');
    const [delta, setDelta] = useState(100 - Math.random() * 200);
    const [index, setIndex] = useState(1);
    const toRotate = ["Técnico en informática.", "Desarrollador de Software.", "Instalación de software."];
    const period = 1000;

    useEffect(() => {
        let ticker = setInterval(() => {
            tick();
        }, delta);

        return () => { clearInterval(ticker) };
    }, [text])



    const tick = () => {
        let i = loopNum % toRotate.length;
        let fullText = toRotate[i];
        let updatedText = isDeleting ? fullText.substring(0, text.length - 1) : fullText.substring(0, text.length + 1);

        setText(updatedText);

        if (isDeleting) {
            setDelta(prevDelta => prevDelta / 2);
        }

        if (!isDeleting && updatedText === fullText) {
            setIsDeleting(true);
            setIndex(prevIndex => prevIndex - 1);
            setDelta(period);
        } else if (isDeleting && updatedText === '') {
            setIsDeleting(false);
            setLoopNum(loopNum + 1);
            setIndex(1);
            setDelta(100);
        } else {
            setIndex(prevIndex => prevIndex + 1);
        }
    }

    return (
        <>


            <Flex align="center" justify="center" py={10} bg={isDark ? 'blackAlpha.500' : 'gray.100'}>
                <div >
                    <Box maxW="1200px">

                        <Flex direction={{ base: 'column', md: 'row' }} align="center" justify="center">

                            <Box flex={5} mx={3} pr={{ base: 0, md: 10 }} textAlign='justify'>

                                <Heading as="h2" size="xl" mb={4}>

                                    SOBRE MÍ

                                </Heading>


                                <Box align='flex-start'>

                                    <TrackVisibility>

                                        {({ isVisible }) =>
                                            <div className={isVisible ? "animate__animated animate__fadeIn" : ""} >
                                                <Text fontSize="2xl" fontWeight="bold" bgGradient="linear(to-r, cyan.400, blue.500, cyan.400)" bgClip='text' >{`Hola! Soy Jonnathan Gallegos `} <span className="txt-rotate" dataPeriod="1000" data-rotate='[ "Desarrollador de Software", "Desarrollador Web","Desarrollador Móvil", "Trabajo de BD SQL - NoSQL" ]'><span className="wrap">{text}</span></span></Text>
                                                {/* <Text fontSize="2xl" fontWeight="bold" bgGradient="linear(to-r, #319795, #3182CE, #3182CE)" bgClip='text' >{`Hola! Soy Jonnathan Gallegos `} <span className="txt-rotate" dataPeriod="1000" data-rotate='[ "Técnico en informática.", "Desarrollador de Software.", "Instalación de software." ]'><span className="wrap">{text}</span></span></Text> */}

                                            </div>}
                                    </TrackVisibility>


                                </Box>

                                <Text fontSize="lg" mb={6}>
                                    <div data-aos="zoom-in-down">
                                        La importancia de estar actualizados en el ámbito tecnológico es un reto que debemos seguir. Me especializado en el campo informático, dando paso por mantenimiento de equipos, actualizaciones remotas y corrección de errores. En el campo del software, implemento integración y despliegue continuo con tecnologías en la nube, utilizo para el lado del cliente Node.js, React.js, Angular, además de integración para el servidor con Spring Boot y Next.js.  Estoy aprendiendo la parte de IA con Python, implementando proyectos que llene el saber del conocimiento del cada día.
                                    </div>
                                </Text>

                                <Text fontSize="lg" mb={6}>
                                    <div data-aos="zoom-in-down">
                                        Manejo de servicios en la nube, como AWS (S3, EC2, IAM, Elastic Beanstalk, RDS) y DigitalOcean (Droplets, Apps, Databases).
                                    </div>
                                </Text>
                                <Text fontSize="lg">
                                    <div data-aos="zoom-in-down">
                                        Despliegue de proyectos en plataformas PaaS para testing (Firebase, Vercel, Render, Railway) y DBaaS (MongoDB Atlas, Planetscale, Aiven).
                                    </div>
                                </Text>
                                <FeatureComponent
                                    icon={<Icon as={FaMailBulk} color={'purple.500'} w={5} h={5} />}
                                    iconBg={useColorModeValue('purple.100', 'purple.900')}
                                    text={'Market Analysis'}
                                />
                                <FeatureComponent
                                    icon={<Icon as={FaMailBulk} color={'purple.500'} w={5} h={5} />}
                                    iconBg={useColorModeValue('purple.100', 'purple.900')}
                                    text={'Market Analysis'}
                                />    <FeatureComponent
                                    icon={<Icon as={FaMailBulk} color={'purple.500'} w={5} h={5} />}
                                    iconBg={useColorModeValue('purple.100', 'purple.900')}
                                    text={'Market Analysis'}
                                />
                            </Box>
                            <Box flex={1} pl={{ base: 0, md: 10 }} textAlign="center">
                                <div data-aos="zoom-in-down">
                                    <Image src={jonnathan1} alt="Mi foto" rounded="30px" boxShadow="lg" maxW={isLessWith ? '250px' : '500px'} p={2} mx="auto" marginTop='30px' />

                                </div>
                            </Box>

                        </Flex>

                    </Box >
                </div >
            </Flex >

        </>
    );
};
