
import { Box, Flex, Heading, Text, Button } from '@chakra-ui/react'

import { RiArrowRightLine } from "react-icons/ri"
import { useCustomNavigate } from '../../hooks/custom-navigate'

export const NotFoundPage = () => {

    const { handlerNavigate } = useCustomNavigate()

    return (
        <Flex height="100vh" alignItems="center" justifyContent="center">

            <Box textAlign="center" py={10} px={6}>
                <Heading
                    display="inline-block"
                    as="h1"
                    fontSize="8xl"
                    fontWeight="extrabold"
                    letterSpacing="wider"
                    bgGradient="linear(to-r, teal.400, teal.600)"
                    backgroundClip="text"
                >
                    Oops!
                </Heading>
                <Text fontSize="18px" mt={3} mb={2} fontWeight="bold"  >
                    404 - PAGE NOT FOUND
                </Text>
                <Text color={'gray.500'} mb={4}>
                    THE PAGE YOU&apos;RE LOOKING FOR DOES NOT SEEM TO EXIST
                </Text>
                <Button colorPalette="teal" variant="outline" alignContent='center' onClick={() => handlerNavigate('/')}>
                    GO TO HOME <RiArrowRightLine />
                </Button>
            </Box>
        </Flex>
    )
}