import React, { useEffect, useState } from 'react';
import { Box, Flex, useColorMode } from '@chakra-ui/react';

import { IconButton } from '@chakra-ui/button';
import { HeaderComponent } from './components/header/HeaderComponent';

import { FooterComponent } from './components/FooterComponent';

import { IoIosArrowDropupCircle } from 'react-icons/io';

import { scrollToSection1 } from './components/scrollToSection';

import { FaWhatsapp } from 'react-icons/fa';

import AOS from 'aos';
import 'aos/dist/aos.css';
import { RouterPage } from './router/router-page';

function App() {
  const { colorMode, toggleColorMode } = useColorMode();
  const isDark = colorMode === 'dark';

  const [showButton, setShowButton] = useState(false);

  useEffect(() => {
    AOS.init({ duration: 1000 });
    AOS.refresh();
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;
      const windowHeight = window.innerHeight;

      const threshold = windowHeight;

      if (scrollY > threshold) {
        setShowButton(true);
      } else {
        setShowButton(false);
      }
    };

    window.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  //Uso del eve
  const hookEvent = e => {
    scrollToSection1(e);
  };

  return (
    <>
      <Flex direction="column" minH="100vh">
        <div id="home" />

        <Box as="header" position="sticky" top="0" zIndex="1000" shadow="md">
          <HeaderComponent />
        </Box>

        <Box as="main" flex="1" overflowY="auto">
          <RouterPage />
        </Box>

        <Box as="footer">
          <FooterComponent />
        </Box>
      </Flex>

      <IconButton
        icon={<FaWhatsapp />}
        size="lg"
        rounded={50}
        colorScheme="green"
        position="fixed"
        bottom="4"
        right="4"
        zIndex="999"
        onClick={() =>
          window.open(
            'https://wa.me/593990093849?text=Hola%2C%20me%20contacto.%20Podr%C3%ADas%20ayudarme.',
            '_blank'
          )
        }
        style={{ fontSize: '30px', width: '60px', height: '60px' }}
      />

      {showButton && (
        <IconButton
          icon={<IoIosArrowDropupCircle />}
          size="lg"
          rounded={50}
          colorScheme="blue"
          position="fixed"
          bottom="4"
          left="4"
          zIndex="999"
          onClick={() => hookEvent('home')}
          style={{
            fontSize: '30px',
            width: '60px',
            height: '60px',
            opacity: 10,

            animation: 'fadeInUp 0.5s ease-in-out forwards',
          }}
        />
      )}
    </>
  );
}

export default App;
