import React from 'react'
import { Box, Flex, Heading, Icon, Text, useBreakpointValue, useColorMode } from '@chakra-ui/react';

export const CardSkill = ({ title, icon, percentage, size }) => {

  const { colorMode, toggleColorMode } = useColorMode();
  const isDark = colorMode === "dark";

  const barStyles = {
    width: `${percentage}%`,
    height: '8px',
    borderRadius: '4px',
    bg: 'blue.500',
  };

  return (
    // Aqui en el box vpy eliminar el margin  m={1}
    <Box rounded="md" shadow="lg" p={4} m={2} width={size}
      bg={isDark ? 'whiteAlpha.100' : ' darkgray'}

      color="gray.800"
      transition="transform 0.3s ease-in-out"
      _hover={{ transform: 'scale(1.05)' }}>
      {/* <Flex direction="column" align="center" mb={4}>
            <Icon as={icon} boxSize={8} color="blue.500" mb={2} />
            <Flex align="center" justify="space-between" width="100%">
              <Box flex="1" bg="gray.200" height="8px" borderRadius="4px" overflow="hidden">
                <Box {...barStyles} />
              </Box>
              <Text fontSize="sm" fontWeight="bold" color="blue.500" ml={2}>
                {percentage}%
              </Text>
            </Flex>
            <Text fontSize="lg" fontWeight="bold" mt={2}>
              {title}
            </Text>
          </Flex> */}
      <Flex direction="column" align="center" >
        <Icon as={icon} boxSize={8} color="blue.500" mb={2} />

        {/* <Text fontSize="sm" align="center" fontWeight="bold" color="blue.500" ml={2}>
          {percentage}%
        </Text>

        <Text fontSize="lg" fontWeight="bold" mt={2}>
          {title}
        </Text> */}
      </Flex>
    </Box>
  );
}
